    """Walk src2/ and tests/ for .py files, returning repo-relative paths."""
    roots = [REPO_ROOT / "src2", REPO_ROOT / "tests"]
    candidates: list[str] = []
    for root in roots:
        if not root.is_dir():
            continue
        for path in sorted(root.rglob("*.py")):
            try:
                rel = str(path.relative_to(REPO_ROOT))
            except ValueError:
                continue
            candidates.append(rel)
    return candidates


def _filter_ignored(candidates: list[str]) -> list[str]:
    """Drop gitignored paths; return all candidates on subprocess failure."""
    if not candidates:
        return []
    import subprocess

    try:
        proc = subprocess.run(
            ["git", "check-ignore", "--stdin", "--no-index"],
            input="\n".join(candidates),
            capture_output=True,
            text=True,
            cwd=str(REPO_ROOT),
            timeout=30,
        )
        ignored = set(proc.stdout.splitlines())
        return [c for c in candidates if c not in ignored]
    except (subprocess.SubprocessError, OSError):
        return candidates


def _render_tree(shown: list[str]) -> str:
    """Render a list of repo-relative .py paths as an indented tree."""
    tree_lines: list[str] = []
    for rel in shown:
        parts = rel.split("/")
        indent = "    " * (len(parts) - 1)
        tree_lines.append(f"{indent}└── {parts[-1]}")
    return "\n".join(tree_lines)


def _py_tree() -> str:
    """Return a filtered, indented tree of tracked ``*.py`` files under src2/ and tests/.

    Walks src2/ and tests/ for .py files, drops any path matched by .gitignore
    (so .beads/, logs/, _prd/, training_data *.json, etc. never appear), and
    renders the remainder as an indented tree by path segments.

    Returns:
        A newline-joined tree string, or a placeholder message when no
        matching files are found.
    """
    candidates = _collect_py_candidates()
    if not candidates:
        return "(no .py sources found under src2/ or tests/)"
    shown = _filter_ignored(candidates)
    if not shown:
        return "(no tracked .py sources found under src2/ or tests/)"
    return _render_tree(shown)"}
